files.content:
.field {
  display: grid;
  min-width: 0;
  width: 100%;
}

.label {
  margin-bottom: var(--space-2);
  color: var(--foreground);
  font-size: var(--text-sm);
  font-weight: 500;
  line-height: var(--leading-body);
}

.inputWrapper {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
}

.input {
  width: 100%;
  min-height: var(--control-height-md);
  padding: 0 var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  background: var(--surface);
  color: var(--foreground);
  font: inherit;
  font-size: var(--text-sm);
  line-height: var(--leading-body);
  outline: none;
  transition:
    border-color var(--duration-fast) var(--ease-standard),
    background-color var(--duration-fast) var(--ease-standard);
}

.input::placeholder {
  color: var(--text-muted);
}

.input:focus {
  border-color: var(--border-strong);
}

.input[data-invalid="true"] {
  border-color: var(--danger);
}

.input:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.prefix,
.suffix {
  position: absolute;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  pointer-events: none;
}

.prefix {
  left: var(--space-3);
}

.suffix {
  right: var(--space-3);
}

.hasPrefix {
  padding-left: calc(var(--space-3) + 20px);
}

.hasSuffix {
  padding-right: calc(var(--space-3) + 24px);
}

.clearButton {
  position: absolute;
  right: var(--space-2);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: 0;
  border-radius: 50%;
  background: var(--surface-muted);
  color: var(--text-secondary);
  cursor: pointer;
  transition: background-color var(--duration-fast) var(--ease-standard);
}

.clearButton:hover {
  background: var(--border);
  color: var(--foreground);
}

.messageRow {
  margin-top: var(--space-1);
  min-height: 1.25em;
  font-size: var(--text-xs);
  line-height: var(--leading-body);
}

.description {
  color: var(--text-muted);
}

.error {
  color: var(--danger);
  font-weight: 500;
}
